defmodule CartPricing.Sales do
  use Ash.Domain

  resources do
    resource CartPricing.Sales.Cart
    resource CartPricing.Sales.CartItem
    resource CartPricing.Sales.Coupon
  end

  def create_cart!(attrs), do: Ash.create!(CartPricing.Sales.Cart, attrs)
  def create_cart_item!(attrs), do: Ash.create!(CartPricing.Sales.CartItem, attrs)
  def create_coupon!(attrs), do: Ash.create!(CartPricing.Sales.Coupon, attrs)
  def get_cart!(id), do: Ash.get!(CartPricing.Sales.Cart, id)
  def get_coupon_by_code!(code), do: Ash.get!(CartPricing.Sales.Coupon, code: code)
  def get_coupon_by_code(code), do: Ash.read_one(CartPricing.Sales.Coupon, code: code)
end
EOF
echo "written sales.ex"

cd /home/user/cart_pricing && sed -i '/calculate :pricing_quote, :map, CartPricing.Sales.Calculations.CartQuote/d' lib/cart_pricing/sales/cart.ex && sed -i '/calculate :item_count, :integer, expr(count(items))/a \    calculate :pricing_quote, :map, expr(
